#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "diag.h"
#include "json.h"
#include "lexer.h"
#include "tokens.h"
typedef struct {int type;SrcLoc loc;} Tok;
static char *read_all(FILE*f,size_t*out_len){size_t cap=4096,len=0;char*buf=malloc(cap);if(!buf)return NULL;size_t n;while((n=fread(buf+len,1,cap-len,f))>0){len+=n;if(len==cap){char*nb=realloc(buf,cap*=2);if(!nb){free(buf);return NULL;}buf=nb;}}if(ferror(f)){free(buf);return NULL;}*out_len=len;return buf;}
static void print_visible(const char*s,size_t len,size_t max){size_t shown=0;for(size_t i=0;i<len&&shown<max;i++,shown++){unsigned char c=(unsigned char)s[i];if(c=='\n')fputs("\\n",stdout);else if(c=='\t')fputs("\\t",stdout);else if(c=='\r')fputs("\\r",stdout);else if(c<0x20||c==0x7f)printf("\\x%02x",c);else putchar(c);}if(len>max)fputs("...",stdout);}
static void print_snippet(const char*src,size_t len,SrcLoc loc){size_t start=0;for(int line=1;line<loc.line&&start<len;start++)if(src[start]=='\n')line++;size_t end=start;while(end<len&&src[end]!='\n'&&src[end]!='\r')end++;printf("  %4d | %.*s\n",loc.line,(int)(end-start),src+start);printf("       | ");for(int i=1;i<loc.col;i++)putchar(start+(size_t)(i-1)<end&&src[start+(size_t)(i-1)]=='\t'?'\t':' ');putchar('^');int span=loc.length,room=(int)(end-start)-(loc.col-1);if(span>room)span=room;for(int i=1;i<span;i++)putchar('~');putchar('\n');}
static void emit_text(const char*name,const char*src,size_t len,const Tok*toks,size_t ntoks){printf("== Lexical analysis: %s ==\n\n",name);printf("%-5s %-9s %-16s %s\n","#","LINE:COL","TOKEN","LEXEME");for(size_t i=0;i<ntoks;i++){char pos[24];snprintf(pos,sizeof pos,"%d:%d",toks[i].loc.line,toks[i].loc.col);printf("%-5zu %-9s %-16s ",i+1,pos,token_name(toks[i].type));print_visible(src+toks[i].loc.offset,(size_t)toks[i].loc.length,48);putchar('\n');}if(diag_count())putchar('\n');for(size_t i=0;i<diag_count();i++){const Diagnostic*d=diag_get(i);printf("%s:%d:%d: %s[%s]: %s\n",name,d->loc.line,d->loc.col,d->severity==SEV_ERROR?"error":"warning",d->code,d->message);print_snippet(src,len,d->loc);}printf("\n%zu token(s), %d error(s), %d warning(s)\n",ntoks,diag_error_count(),diag_warning_count());}
static void emit_json(const char*name,const char*src,const Tok*toks,size_t ntoks){printf("{\n  \"phase\": \"lexical\",\n  \"file\": ");json_write_string(stdout,name,strlen(name));printf(",\n  \"tokens\": [");for(size_t i=0;i<ntoks;i++){const Tok*t=&toks[i];printf("%s\n    {\"id\": %zu, \"type\": \"%s\", \"category\": \"%s\", \"lexeme\": ",i?",":"",i+1,token_name(t->type),token_category_name(token_category(t->type)));json_write_string(stdout,src+t->loc.offset,(size_t)t->loc.length);printf(", \"line\": %d, \"column\": %d, \"offset\": %d, \"length\": %d, \"error\": %s}",t->loc.line,t->loc.col,t->loc.offset,t->loc.length,t->type==TOK_ERROR?"true":"false");}printf("%s],\n  \"diagnostics\": [",ntoks?"\n  ":"");for(size_t i=0;i<diag_count();i++){const Diagnostic*d=diag_get(i);printf("%s\n    {\"code\": \"%s\", \"severity\": \"%s\", \"message\": ",i?",":"",d->code,d->severity==SEV_ERROR?"error":"warning");json_write_string(stdout,d->message,strlen(d->message));printf(", \"lexeme\": ");json_write_string(stdout,d->lexeme,strlen(d->lexeme));printf(", \"line\": %d, \"column\": %d, \"offset\": %d, \"length\": %d}",d->loc.line,d->loc.col,d->loc.offset,d->loc.length);}printf("%s],\n  \"summary\": {\"tokens\": %zu, \"errors\": %d, \"warnings\": %d}\n}\n",diag_count()?"\n  ":"",ntoks,diag_error_count(),diag_warning_count());}
static void usage(const char*prog){fprintf(stderr,"Usage: %s [--json] [--comments] [FILE | -]\n",prog);}
int main(int argc,char**argv){int json=0;const char*path="-";for(int i=1;i<argc;i++){if(!strcmp(argv[i],"--json"))json=1;else if(!strcmp(argv[i],"--comments"))lex_emit_comments=1;else if(!strcmp(argv[i],"-h")||!strcmp(argv[i],"--help")){usage(argv[0]);return 0;}else if(argv[i][0]=='-'&&argv[i][1]!='\0'){usage(argv[0]);return 2;}else path=argv[i];}FILE*in=strcmp(path,"-")?fopen(path,"rb"):stdin;if(!in){perror(path);return 2;}size_t len=0;char*src=read_all(in,&len);if(in!=stdin)fclose(in);if(!src){fprintf(stderr,"%s: failed to read input\n",path);return 2;}const char*name=strcmp(path,"-")?path:"<stdin>";Tok*toks=NULL;size_t ntoks=0,cap=0;diag_reset();lexer_init(src,len);for(int t;(t=lexer_next())!=TOK_EOF;){if(ntoks==cap){cap=cap?cap*2:256;Tok*nt=realloc(toks,cap*sizeof*toks);if(!nt){fputs("out of memory\n",stderr);return 2;}toks=nt;}toks[ntoks].type=t;toks[ntoks].loc=lex_tok_loc;ntoks++;}lexer_destroy();if(json)emit_json(name,src,toks,ntoks);else emit_text(name,src,len,toks,ntoks);int rc=diag_error_count()?1:0;free(toks);free(src);diag_reset();return rc;}
